using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleCorruptedAnimalsList", menuName = "Data/Battle/Corrupted Animals/BattleCorruptedAnimals List")]
public class BattleCorruptedAnimalsList : ScriptableObject
{
	[Header("Corrupted Animals")]
	[SerializeField]
	private List<BattleCorruptedAnimals> enemiesPackages = new List<BattleCorruptedAnimals>();

	public List<BattleCorruptedAnimals> EnemiesPackages => enemiesPackages;

	public BattleCorruptedAnimals GetEnemyPackage(string enemyPackageName)
	{
		string text = enemyPackageName.Replace(" ", "").ToLower();
		for (int i = 0; i < enemiesPackages.Count; i++)
		{
			if (text == enemiesPackages[i].name.ToLower())
			{
				return enemiesPackages[i];
			}
		}
		return null;
	}
}
